mapper.select:
SELECT 
FROM membership_order
WHERE id = #{orderId,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}

UPDATE membership_order
SET payment_started_at = #{startedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    state_version = state_version + 1,
    updated_at = #{startedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{orderId,jdbcType=BINARY}
  AND login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND status = #{pendingStatus,jdbcType=SMALLINT,typeHandler=com.example.temperate.mapper.typehandler.MembershipOrderStatusTypeHandler}
  AND payment_started_at IS NULL
  AND expires_at > #{startedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
RETURNING

SELECT 
FROM membership_order
WHERE login_identity_id = #{loginIdentityId,jdbcType=BIGINT}
  AND membership_tier = #{membershipTier,jdbcType=SMALLINT,typeHandler=com.example.temperate.mapper.typehandler.MembershipTierTypeHandler}
  AND status = #{paidStatus,jdbcType=SMALLINT,typeHandler=com.example.temperate.mapper.typehandler.MembershipOrderStatusTypeHandler}
ORDER BY paid_at DESC NULLS LAST, created_at DESC, id DESC
LIMIT 1
